SELECT COUNT(*) AS record_count
FROM federal_facilities_energy
WHERE province = 'NS';

SELECT COUNT(*) AS nb_record_count
FROM federal_facilities_energy
WHERE province = 'NB';

SELECT COUNT(DISTINCT federal_organization) AS distinct_organizations_in_PE
FROM federal_facilities_energy
WHERE province = 'PE' AND federal_organization IS NOT NULL;

SELECT COUNT(*) AS num_records_in_halifax
FROM federal_facilities_energy
WHERE trim(city) ILIKE 'Halifax';
